// ==UserScript==
// @name         Notme YouTube Music Ad Skipper
// @namespace    notmevalo
// @version      1.0
// @description  Skip/mute YouTube Music video ads and remove common ad/promo overlays
// @match        https://music.youtube.com/*
// @run-at       document-start
// ==/UserScript==

(() => {
    'use strict';

    const TAG = '[Notme YTM]';
    let lastAdState = false;

    const skipSelectors = [
        '.ytp-ad-skip-button',
        '.ytp-ad-skip-button-modern',
        '.ytp-skip-ad-button',
        'button.ytp-ad-skip-button',
        'button.ytp-ad-skip-button-modern',
        '[id*="skip-button"] button',
        '.videoAdUiSkipButton'
    ];

    const removableSelectors = [
        '.ytp-ad-overlay-container',
        '.ytp-ad-text-overlay',
        '.ytp-ad-player-overlay',
        'ytmusic-mealbar-promo-renderer',
        'ytmusic-guide-entry-renderer[is-promoted]',
        '[class*="ad-overlay"]'
    ];

    function getPlayer() {
        return document.querySelector('#movie_player');
    }

    function getVideo() {
        return document.querySelector('video');
    }

    function isAdPlaying() {
        const player = getPlayer();

        return !!(
            player &&
            (
                player.classList.contains('ad-showing') ||
                player.classList.contains('ad-interrupting') ||
                player.classList.contains('ytp-ad-overlay-open')
            )
        );
    }

    function clickSkipButtons() {
        for (const selector of skipSelectors) {
            const elements = document.querySelectorAll(selector);

            for (const el of elements) {
                try {
                    if (
                        el &&
                        !el.disabled &&
                        el.offsetParent !== null
                    ) {
                        el.click();
                    }
                } catch (_) {}
            }
        }
    }

    function removeAdOverlays() {
        for (const selector of removableSelectors) {
            document.querySelectorAll(selector).forEach(el => {
                try {
                    el.remove();
                } catch (_) {}
            });
        }
    }

    function skipCurrentAd() {
        if (!isAdPlaying()) {
            if (lastAdState) {
                const video = getVideo();

                if (video) {
                    try {
                        video.muted = false;
                        video.playbackRate = 1;
                    } catch (_) {}
                }
            }

            lastAdState = false;
            return;
        }

        lastAdState = true;

        const video = getVideo();

        if (video) {
            try {
                // Prevent ad audio while we are skipping it.
                video.muted = true;

                // Run skippable countdowns extremely quickly.
                video.playbackRate = 16;

                // If the ad duration is already known, jump close to the end.
                if (
                    Number.isFinite(video.duration) &&
                    video.duration > 1
                ) {
                    const target = Math.max(
                        video.currentTime,
                        video.duration - 0.15
                    );

                    if (target > video.currentTime) {
                        video.currentTime = target;
                    }
                }
            } catch (_) {}
        }

        clickSkipButtons();
        removeAdOverlays();
    }

    function run() {
        try {
            skipCurrentAd();
            clickSkipButtons();
            removeAdOverlays();
        } catch (e) {
            console.debug(TAG, e);
        }
    }

    // YouTube changes the player DOM dynamically.
    const observer = new MutationObserver(run);

    function start() {
        if (!document.documentElement) {
            requestAnimationFrame(start);
            return;
        }

        observer.observe(document.documentElement, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['class', 'style', 'hidden']
        });

        // Backup polling because some player state changes don't mutate
        // the elements our observer happens to see.
        setInterval(run, 250);

        run();
    }

    start();
})();

// ==UserScript==
// @name         NotmeMovies - Einthusan Session Helper
// @namespace    notmevalo.movies
// @version      1.1
// @match        https://einthusan.tv/*
// @match        https://www.einthusan.tv/*
// @run-at       document-idle
// ==/UserScript==

(function () {
    'use strict';

    const log = (...args) =>
        console.log('[NotmeMovies Einthusan]', ...args);

    function authenticated() {
        const selectors = [
            'a[href*="logout"]',
            'a[href*="signout"]',
            'a[href*="/account"]',
            'a[href*="/profile"]',
            '.logout',
            '.signout'
        ];

        if (selectors.some(s => document.querySelector(s))) {
            return true;
        }

        const text =
            (document.body?.innerText || '').toLowerCase();

        return (
            text.includes('logout') ||
            text.includes('log out') ||
            text.includes('sign out')
        );
    }

    function looksLikeLogin(el) {
        const text =
            (el?.innerText || el?.textContent || '')
                .toLowerCase();

        return (
            text.includes('please login') &&
            text.includes('password') &&
            (
                text.includes('forgot password') ||
                text.includes('log in with google')
            )
        );
    }

    function removeStaleLoginOverlay() {
        if (!authenticated()) {
            return;
        }

        const elements =
            document.querySelectorAll(
                'div, section, aside, form'
            );

        for (const el of elements) {
            if (!looksLikeLogin(el)) continue;

            let node = el;

            for (let i = 0; i < 7 && node; i++) {
                const style = getComputedStyle(node);
                const rect = node.getBoundingClientRect();

                if (
                    style.position === 'fixed' ||
                    (
                        rect.width > innerWidth * 0.65 &&
                        rect.height > innerHeight * 0.45
                    )
                ) {
                    node.style.setProperty(
                        'display',
                        'none',
                        'important'
                    );

                    log('Removed stale authenticated login overlay');
                    break;
                }

                node = node.parentElement;
            }
        }

        document.documentElement.style.removeProperty('overflow');
        document.body?.style.removeProperty('overflow');
    }

    function resumePlayer() {
        if (!authenticated()) return;

        const videos = document.querySelectorAll('video');

        for (const video of videos) {
            if (
                video.currentSrc?.includes('einthusan.io') ||
                video.src?.includes('einthusan.io')
            ) {
                video.play().catch(() => {});
            }
        }
    }

    function fix() {
        removeStaleLoginOverlay();
        resumePlayer();
    }

    fix();

    const observer = new MutationObserver(() => {
        clearTimeout(window.__notmeSessionHelper);
        window.__notmeSessionHelper =
            setTimeout(fix, 150);
    });

    observer.observe(document.documentElement, {
        subtree: true,
        childList: true
    });
})();

// ==UserScript==
// @name         NotmeMovies YouTube Ad Cleaner
// @namespace    notmevalo.movies
// @version      1.0.0
// @description  Removes common YouTube ads and skips player ads inside NotmeMovies WebView.
// @match        https://www.youtube.com/*
// @match        https://m.youtube.com/*
// @run-at       document-start
// ==/UserScript==

(function () {
    'use strict';

    const TAG = '[NotmeMovies YouTube]';

    // Ad/promoted elements that can safely be hidden.
    const HIDE_SELECTORS = [
        'ytd-display-ad-renderer',
        'ytd-promoted-sparkles-web-renderer',
        'ytd-promoted-video-renderer',
        'ytd-ad-slot-renderer',
        'ytd-in-feed-ad-layout-renderer',
        'ytd-banner-promo-renderer',
        'ytd-statement-banner-renderer',
        'ytd-player-legacy-desktop-watch-ads-renderer',
        'ytd-action-companion-ad-renderer',
        'ytd-companion-slot-renderer',
        'ytm-promoted-sparkles-web-renderer',

        '#masthead-ad',
        '#player-ads',
        '#panels-full-bleed-container',
        '.video-ads',
        '.ytp-ad-overlay-container',
        '.ytp-ad-player-overlay',
        '.ytp-ad-message-container',
        '.ytp-ad-text-overlay',
        '.ytp-ad-image-overlay',
        '.ytp-ad-overlay-slot'
    ];

    const style = document.createElement('style');
    style.textContent = `
        ${HIDE_SELECTORS.join(',')} {
            display: none !important;
            visibility: hidden !important;
            opacity: 0 !important;
            pointer-events: none !important;
        }
    `;

    function installStyle() {
        if (!style.isConnected) {
            (document.head || document.documentElement).appendChild(style);
        }
    }

    installStyle();

    function clickSkipButtons() {
        const selectors = [
            '.ytp-ad-skip-button',
            '.ytp-ad-skip-button-modern',
            '.ytp-skip-ad-button',
            'button.ytp-ad-skip-button',
            'button.ytp-ad-skip-button-modern',
            '.videoAdUiSkipButton',
            '[id*="skip-button"]'
        ];

        for (const selector of selectors) {
            document.querySelectorAll(selector).forEach(button => {
                try {
                    if (button && button.offsetParent !== null) {
                        button.click();
                    }
                } catch (_) {}
            });
        }
    }

    let normalMuted = false;
    let normalRate = 1;

    function handlePlayerAd() {
        const player =
            document.querySelector('#movie_player') ||
            document.querySelector('.html5-video-player');

        const video = document.querySelector('video');

        if (!player || !video) {
            return;
        }

        const adPlaying =
            player.classList.contains('ad-showing') ||
            player.classList.contains('ad-interrupting');

        if (adPlaying) {
            try {
                if (!video.dataset.notmeAdActive) {
                    video.dataset.notmeAdActive = '1';
                    normalMuted = video.muted;
                    normalRate = video.playbackRate || 1;
                }

                video.muted = true;

                try {
                    video.playbackRate = 16;
                } catch (_) {}

                // If duration is already known, jump close to the end.
                if (
                    Number.isFinite(video.duration) &&
                    video.duration > 0 &&
                    video.duration - video.currentTime > 0.5
                ) {
                    try {
                        video.currentTime = Math.max(
                            video.currentTime,
                            video.duration - 0.15
                        );
                    } catch (_) {}
                }

                clickSkipButtons();

            } catch (_) {}

        } else if (video.dataset.notmeAdActive) {
            delete video.dataset.notmeAdActive;

            try {
                video.muted = normalMuted;
            } catch (_) {}

            try {
                video.playbackRate = normalRate || 1;
            } catch (_) {}
        }
    }

    function removeAdNodes() {
        for (const selector of HIDE_SELECTORS) {
            document.querySelectorAll(selector).forEach(node => {
                try {
                    node.style.setProperty('display', 'none', 'important');
                } catch (_) {}
            });
        }
    }

    function clean() {
        installStyle();
        clickSkipButtons();
        removeAdNodes();
        handlePlayerAd();
    }

    // YouTube is a SPA, so watch for dynamically inserted ad controls.
    const observer = new MutationObserver(() => {
        clean();
    });

    function startObserver() {
        if (!document.documentElement) {
            setTimeout(startObserver, 50);
            return;
        }

        observer.observe(document.documentElement, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['class']
        });

        clean();
    }

    startObserver();

    // MutationObserver alone can miss player-state transitions.
    setInterval(clean, 500);

    window.addEventListener('yt-navigate-finish', clean, true);
    window.addEventListener('yt-page-data-updated', clean, true);

    console.log(TAG, 'loaded');
})();
